mapper.select:


    c.status <> 'DRAFT'
    AND c.status = #{status}
    AND c.supplier_id = #{supplierId}

        AND (c.claim_no LIKE CONCAT('%', #{keyword}, '%') OR s.name LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY c.id DESC

SELECT supplier_id AS "supplierId", COUNT(*) AS "claims", SUM(amount) AS "amount"
FROM qms_supplier_claim
WHERE status = 'CONFIRMED'
  AND supplier_id IN #{id}
  AND claim_date >= #{beginDate}
  AND claim_date <= #{endDate}
GROUP BY supplier_id
